round:#fff}.candidate-browser__status{padding:.8rem 0;color:#94a3b8;font-size:.78rem}.candidate-browser__grid{display:grid;grid-template-columns:repeat(4,1fr);gap:.75rem;max-height:430px;overflow:auto}.candidate-option{padding:.55rem;border:1px solid #334155;border-radius:12px;background:#1e293b;color:#fff;cursor:pointer;transition:.18s}.candidate-option:hover{transform:translateY(-2px);border-color:#60a5fa;background:#243550}.candidate-option img{width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:9px}.candidate-option strong,.candidate-option span{display:block}.candidate-option strong{margin-top:.55rem;font-size:.76rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.candidate-option span{font-size:.66rem;color:#94a3b8}
@media(max-width:767.98px){.live-polling__head{flex-direction:column}.live-polling__time{width:100%}.live-polling__packages article{grid-template-columns:1fr}.live-package-value{text-align:left}.candidate-role-grid{grid-template-columns:1fr}.candidate-browser__toolbar{align-items:stretch;flex-wrap:wrap}.candidate-search{flex-basis:100%}.candidate-browser__grid{grid-template-columns:repeat(2,1fr)}}
</style>
@stop

@section('js')
<script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
<script>
const packages=@json($packageData);
const packageStoreUrl=@json(route('admin.osis-election.packages.store',$election));
const candidateUrl=@json(route('admin.osis-election.candidates',$election));
const candidateFields=['chairman_id','secretary_id','treasurer_id'];
let activeCandidateField=null,candidateSearchTimer=null,candidateRequest=null,visibleCandidates={};
function escapeHtml(value){return $('<div>').text(value??'').html()}
function selectedCandidateIds(exceptField=null){const f=document.getElementById('packageForm');return candidateFields.filter(k=>k!==exceptField&&f.elements[k].value).map(k=>f.elements[k].value)}
function renderCandidateRole(field,student=null){const card=document.querySelector(`.candidate-role[data-field="${field}"]`),input=document.getElementById('packageForm').elements[field],img=card.querySelector('img'),icon=card.querySelector('.candidate-role__photo i');input.value=student?.id||'';card.querySelector('strong').textContent=student?.name||'Belum dipilih';card.querySelector('small').textContent=student?`${student.class} · NISN ${student.nisn||'-'}`:'Klik untuk memilih siswa';if(student){img.src=student.photo;img.alt=student.name;img.hidden=false;icon.hidden=true;card.querySelector('button').innerHTML='<i class="fas fa-exchange-alt mr-1"></i>Ganti '+card.querySelector('span').textContent}else{img.hidden=true;img.removeAttribute('src');icon.hidden=false;card.querySelector('button').innerHTML='<i class="fas fa-search mr-1"></i>Pilih '+card.querySelector('span').textContent}}
function resetCandidateRoles(){candidateFields.forEach(field=>renderCandidateRole(field));document.getElementById('candidateBrowser').hidden=true;document.getElementById('candidateSearch').value=''}
async function loadCandidates(search=''){if(!activeCandidateField)return;if(candidateRequest)candidateRequest.abort();candidateRequest=new AbortController();const params=new URLSearchParams({search,current_package_id:document.getElementById('currentPackageId').value});selectedCandidateIds(activeCandidateField).forEach(id=>params.append('exclude_ids[]',id));const status=document.getElementById('candidateBrowserStatus'),grid=document.getElementById('candidateBrowserGrid');status.textContent='Memuat siswa yang tersedia...';grid.innerHTML='';try{const response=await fetch(candidateUrl+'?'+params.toString(),{headers:{Accept:'application/json'},signal:candidateRequest.signal});if(!response.ok)throw new Error('Gagal memuat kandidat');const data=await response.json();visibleCandidates=Object.fromEntries(data.students.map(student=>[student.id,student]));status.textContent=data.students.length?`${data.students.length} siswa tersedia · siswa yang sudah dipakai otomatis disembunyikan`:'Tidak ada siswa yang sesuai.';grid.innerHTML=data.students.map(student=>`<button type="button" class="candidate-option" data-student-id="${escapeHtml(student.id)}"><img src="${escapeHtml(student.photo)}" alt="${escapeHtml(student.name)}"><strong>${escapeHtml(student.name)}</strong><span>${escapeHtml(student.class)} · ${escapeHtml(student.nisn||'-')}</span></button>`).join('')}catch(error){if(error.name!=='AbortError')status.textContent='Data kandidat gagal dimuat. Silakan coba lagi.'}}
$(document).on('click','.btn-open-candidate',function(){activeCandidateField=this.dataset.field;document.getElementById('candidateRoleLabel').textContent=this.dataset.label;document.getElementById('candidateBrowser').hidden=false;document.getElementById('candidateSearch').value='';loadCandidates();setTimeout(()=>document.getElementById('candidateSearch').focus(),100)});
$(document).on('click','.candidate-option',function(){renderCandidateRole(activeCandidateField,visibleCandidates[this.dataset.studentId]);document.getElementById('candidateBrowser').hidden=true;activeCandidateField=null});
$('#candidateSearch').on('input',function(){clearTimeout(candidateSearchTimer);candidateSearchTimer=setTimeout(()=>loadCandidates(this.value.trim()),300)});
$('#closeCandidateBrowser').on('click',function(){document.getElementById('candidateBrowser').hidden=true;activeCandidateField=null});
$('[data-target="#packageModal"]').on('click',function(){const f=document.getElementById('packageForm');f.reset();f.action=packageStoreUrl;$('#packageMethod').val('POST');$('#currentPackageId').val('');$('.modal-title').text('Tambah Paket');resetCandidateRoles()});
$('.btn-edit-package').on('click',function(){const id=$(this).data('id'),p=packages[id],f=document.getElementById('packageForm');f.reset();f.action=p.url;$('#packageMethod').val('PUT');$('#currentPackageId').val(id);$('.modal-title').text('Edit Paket '+p.number);['number','name','slogan','vision','mission','programs','message'].forEach(k=>f.elements[k].value=p[k]??'');candidateFields.forEach(k=>renderCandidateRole(k,p.candidates[k]));document.getElementById('candidateBrowser').hidden=true;$('#packageModal').modal('show')});
$('.confirm-form').on('submit',function(e){e.preventDefault();const f=this;Swal.fire({icon:'question',title:'Konfirmasi',text:f.dataset.confirm,showCancelButton:true,confirmButtonText:'Ya, lanjutkan',cancelButtonText:'Batal',confirmButtonColor:'#2563eb'}).then(r=>{if(r.isConfirmed)f.submit()})});
const livePolling=document.getElementById('livePolling');if(livePolling){const refreshLivePolling=async()=>{const icon=document.getElementById('livePollingIcon');icon.classList.add('fa-spin');try{const response=await fetch(livePolling.dataset.url,{headers:{Accept:'application/json'},cache:'no-store'});if(!response.ok)throw new Error();const data=await response.json();document.getElementById('liveVoted').textContent=Number(data.voted).toLocaleString('id-ID');document.getElementById('liveRemaining').textContent=Number(data.remaining).toLocaleString('id-ID');document.getElementById('liveTurnout').textContent=data.turnout+'%';document.getElementById('livePollingTime').textContent=data.updated_at;data.packages.forEach(item=>{const row=document.querySelector(`[data-package-id="${item.id}"]`);if(!row)return;row.querySelector('.live-bar span').style.width=item.percentage+'%';row.querySelector('.live-package-value strong').textContent=Number(item.votes).toLocaleString('id-ID');row.querySelector('.live-package-value span').textContent=item.percentage+'%'})}finally{icon.classList.remove('fa-spin')}};setInterval(()=>{if(!document.hidden)refreshLivePolling()},3000)}
@if(session('success'))Swal.fire({icon:'success',title:'Berhasil',text:@json(session('success')),confirmButtonColor:'#2563eb'});@endif
@if(session('error'))Swal.fire({icon:'error',title:'Belum dapat diproses',text:@json(session('error')),confirmButtonColor:'#2563eb'});@endif
@if($errors->any())Swal.fire({icon:'error',title:'Periksa isian',html:@json(implode('<br>',$errors->all())),confirmButtonColor:'#2563eb'}).then(()=>$('#packageModal').modal('show'));@endif
</script>
@stop
